export function mountMaterials(form,{score,request,onStatus}){
 const panel=document.createElement('details');panel.className='classroom-materials';panel.innerHTML='<summary>教材与课堂材料</summary><label>材料用途<select><option value="textbook">教材</option><option value="lesson-plan">教案</option><option value="audio">聆听素材</option><option value="reference">参考资料</option></select></label><label class="classroom-material-picker">添加文件<input type="file" multiple accept=".pdf,.docx,.txt,.md,.png,.jpg,.jpeg,.webp,audio/*,video/*"></label><div class="classroom-material-list"></div><progress hidden max="100" value="0"></progress><output></output>';
 form.querySelector('.classroom-options').before(panel);
 const list=panel.querySelector('.classroom-material-list'),input=panel.querySelector('input'),progress=panel.querySelector('progress'),output=panel.querySelector('output');let items=[],bound=null,poll=null,epoch=0;const chosen=new Set();
 function render(){list.replaceChildren();for(const item of items){const row=document.createElement('label'),box=document.createElement('input'),text=document.createElement('span');box.type='checkbox';box.checked=chosen.has(item.id);box.disabled=item.status!=='ready';box.onchange=()=>box.checked?chosen.add(item.id):chosen.delete(item.id);text.textContent=item.name+' — '+(item.status==='ready'?(item.transcriptionStatus&&item.transcriptionStatus!=='ready'?item.message:'已解析'):`${item.progress||0}% ${item.message||'等待解析'}`);row.append(box,text);if(item.status==='failed'||item.transcriptionStatus==='failed'){const retry=document.createElement('button');retry.type='button';retry.textContent='重试';retry.onclick=async()=>{retry.disabled=true;try{await request('/api/classroom/material-retry',{materialId:item.id});await refresh()}catch(error){onStatus(error.message)}finally{retry.disabled=false}};row.append(retry)}list.append(row);}}
 async function refresh(){const id=score()?.serverId;if(id!==bound){bound=id;epoch++;items=[];chosen.clear();clearTimeout(poll);render()}if(!id)return;const version=epoch;try{const result=await request('/api/classroom/materials?scoreId='+id);if(version!==epoch)return;const previous=new Set(items.filter(i=>i.status==='ready').map(i=>i.id));items=result.materials;for(const item of items)if(item.status==='ready'&&!previous.has(item.id))chosen.add(item.id);render();clearTimeout(poll);if(items.some(i=>['queued','uploading','processing'].includes(i.status)))poll=setTimeout(refresh,1800);}catch(error){onStatus(error.message)}}
 async function chunkRequest(body,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/classroom/material-upload');xhr.timeout=60000;xhr.setRequestHeader('Content-Type','application/json');xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress(e.loaded/e.total)};xhr.onerror=()=>reject(Error('材料上传连接中断，已接收的分片保留，重新选择同一文件可继续'));xhr.ontimeout=()=>reject(Error('材料上传超时，已接收的分片保留'));xhr.onload=()=>{try{const data=JSON.parse(xhr.responseText);if(xhr.status>=400||data.error)throw Error(data.error||'上传失败');resolve(data)}catch(error){reject(error)}};xhr.send(JSON.stringify(body))})}
 input.onchange=async()=>{const files=[...input.files],id=score()?.serverId,version=epoch;if(!id){onStatus('请先打开一首云曲谱');return}input.disabled=true;progress.hidden=false;try{for(const [number,file]of files.entries()){output.textContent=`${number+1}/${files.length} 正在校验 ${file.name}`;const bytes=new Uint8Array(await file.arrayBuffer()),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');let offset=0;while(offset<bytes.length){const end=Math.min(bytes.length,offset+384*1024),part=bytes.subarray(offset,end);let binary='';for(let i=0;i<part.length;i+=8192)binary+=String.fromCharCode(...part.subarray(i,i+8192));const result=await chunkRequest({scoreId:id,digest,name:file.name,size:file.size,offset,kind:panel.querySelector('select').value,chunk:btoa(binary)},fraction=>{progress.value=(number+(offset+part.length*fraction)/file.size)/files.length*100;output.textContent=`${file.name} 上传 ${Math.floor((offset+part.length*fraction)/file.size*100)}%`});if(result.status!=='uploading'){offset=bytes.length;if(result.status==='failed')throw Error(result.message)}else offset=result.offset;}if(version===epoch)await refresh();}progress.value=100;output.textContent='上传完成，正在后台解析材料';}catch(error){output.textContent=error.message}finally{input.disabled=false;input.value='';if(version===epoch)void refresh()}};
 document.addEventListener('practice-state',()=>{if(score()?.serverId!==bound)void refresh()});void refresh();
 return {ids:()=>[...chosen],refresh};
}
